// Причины отказа, по которым сделку не анализируем совсем.
//
// Началось с «Дубля» (решение Сани 06.10.2026), 16.10 добавлен «Дополнительный контакт».
// Логика у обеих причин одна: это технические сделки, общения в них нет — оно идёт в основной
// сделке, к которой они привязаны. По дублям за всё время было 49 сделок и 52 разбора,
// 304 минуты работы конвейера и 1 012 855 входных токенов, причём в 33 случаях из 52 судья
// отвечал «недостаточно данных» — деньги тратились на заведомо пустой разбор.
//
// Что делаем: сделку пропускаем до транскрипции и анализа. Карточку в `lost_deals` пишем как
// обычно, чтобы было видно, что сделка была. В `lost_deal_analyses` не пишем ничего — значит
// такая сделка не попадёт ни в `lost_pipeline_attention`, ни в ночной повтор. Комментарий
// в карточку Битрикса не пишется, РОПам не уходит.
//
// Как сравнивать. В сделке Битрикс хранит ИДЕНТИФИКАТОР значения списка
// (`UF_CRM_1584703948317`), а текст подставляется из справочника `crm.deal.userfield.list`.
// Поэтому основной признак — идентификатор: он переживёт переименование значения в Битриксе.
// Текст оставлен запасным: он сработает, если значение пересоздадут с новым идентификатором.
// Срабатывает любой из двух признаков.
//
// Чтобы добавить причину: дописать текст в SKIP_LOSE_REASONS и пару «идентификатор → текст»
// в SKIP_LOSE_REASON_IDS. Идентификатор брать из справочника Битрикса, а не на память.
//
// Источник правок — этот файл. Моки: tests/duplicate-skip/run.js

// Тексты причин, без учёта регистра и пробелов по краям. Запасной признак.
var SKIP_LOSE_REASONS = ['дубль', 'дополнительный контакт'];

// Идентификаторы значений справочника причин отказа — основной признак.
// Сверено с `crm.deal.userfield.list` 16.10.2026: поле UF_CRM_1584703948317,
// тип enumeration, 22 значения. Похожих по тексту значений в справочнике нет,
// так что лишнего не отсечём.
var SKIP_LOSE_REASON_IDS = {
  '3297': 'дубль',
  '3131': 'дополнительный контакт'
};

// Какая именно причина сработала, или null. Ключ нужен не только для решения «пропускать ли»,
// но и для счётчика в ответе вебхука: по нему видно, сколько сделок отсеклось по каждой причине.
function skipLoseReasonKey(reasonId, reasonText) {
  if (reasonId !== null && reasonId !== undefined) {
    var byId = SKIP_LOSE_REASON_IDS[String(reasonId).trim()];
    if (byId) return byId;
  }
  var t = String(reasonText === null || reasonText === undefined ? '' : reasonText).trim().toLowerCase();
  for (var i = 0; i < SKIP_LOSE_REASONS.length; i++) {
    if (t === SKIP_LOSE_REASONS[i]) return SKIP_LOSE_REASONS[i];
  }
  return null;
}

function isSkipLoseReason(reasonId, reasonText) {
  return skipLoseReasonKey(reasonId, reasonText) !== null;
}
